 D=(q[tet[:,1:]]-q[tet[:,0,None]]).transpose(0,2,1);vol=np.linalg.det(D)/6;mass=np.zeros(len(q));rho=1000.
 for cell,V in zip(tet,vol):mass[cell]+=rho*V/4
 analytic=.5*N*np.sin(2*np.pi/N)*(ro*ro-ri*ri)*length;assert vol.min()>0 and abs(vol.sum()-analytic)<=1e-20;centre=(mass[:,None]*q).sum(0)/mass.sum();velocity=np.array([.001,-.002,.003])+np.cross([.1,.2,.3],q-centre);root=ET.parse(BASE/'results/direct_fem1933/scene.scn').getroot();root.remove(root.find('DefaultAnimationLoop'));ET.SubElement(root,'FreeMotionAnimationLoop');ET.SubElement(root,'GenericConstraintCorrection');ET.SubElement(root,'BlockGaussSeidelConstraintSolver',name='constraints',tolerance='1e-12',maxIterations='1000',computeConstraintForces='1');soft=Path('/home/ubuntu/SOFA/v26.06.00/plugins/SoftRobots/lib/libSoftRobots.so')
