 flat=lambda x:' '.join(format(float(v),'.17g') for v in np.array(x).ravel());node=root.find("Node[@name='support']");node.find('MeshTopology').set('position',flat(q));node.find('MeshTopology').set('tetrahedra',flat(tet));node.find('MechanicalObject').set('position',flat(q));node.find('MechanicalObject').set('velocity',flat(velocity));node.find('DiagonalMass').set('vertexMass',flat(mass));dt=float(root.get('dt'));point=ET.SubElement(node,'Node',name='idealBore');ET.SubElement(point,'MechanicalObject',template='Vec3d',name='point',position=flat(centre));ET.SubElement(point,'CenterOfMassMultiMapping',template='Vec3d,Vec3d',input='@../dofs',output='@point',mapMatrices='1');anchor=np.array([.02,.02,0]);ET.SubElement(point,'CableConstraint',template='Vec3d',name='input',indices='0',pullPoint=flat(anchor),valueType='force',value=str(1.5*dt),minForce='0');ET.SubElement(point,'NativePointJournal',body='@point',filename=str(out/'port.csv'));ET.SubElement(root,'NativeConstraintJournal',solver='@constraints',filename=str(out/'constraints.csv'))
